class Solution {
public:
    long long appealSum(std::string s) {
        std::vector<int> last(26, -1);
        long long total = 0, running = 0;
        for (int i = 0; i < (int)s.size(); ++i) {
            int idx = s[i] - 'a';
            running += (i - last[idx]);
            total += running;
            last[idx] = i;
        }
        return total;
    }
};

class Solution {
    public long appealSum(String s) {
        int[] last = new int[26];
        java.util.Arrays.fill(last, -1);
        long total = 0, running = 0;
        for (int i = 0; i < s.length(); i++) {
            int idx = s.charAt(i) - 'a';
            running += (i - last[idx]);
            total += running;
            last[idx] = i;
        }
        return total;
    }
}

var appealSum = function(s) {
    const last = new Int32Array(26).fill(-1);
    let total = 0, running = 0;
    for (let i = 0; i < s.length; i++) {
        const idx = s.charCodeAt(i) - 97;
        running += (i - last[idx]);
        total += running;
        last[idx] = i;
    }
    return total;
};
